<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'

interface Traveler {
  id: number
  startX: number
  startY: number
  destX: number
  destY: number
  cx: number
  cy: number
  progress: number
  radius: number
}

// Verified inner land coordinates (safely on solid ground, avoiding lakes & coastlines)
const landPoints = [
  { name: 'Managua', x: 585, y: 550 },
  { name: 'Tipitapa / Boaco West', x: 700, y: 520 },
  { name: 'Juigalpa / Chontales', x: 800, y: 590 },
  { name: 'Matagalpa Center', x: 675, y: 430 },
  { name: 'Jinotega Center', x: 785, y: 200 },
  { name: 'Estelí Center', x: 590, y: 390 },
  { name: 'Somoto / Madriz', x: 590, y: 310 },
  { name: 'Ocotal / Nueva Segovia', x: 670, y: 250 },
  { name: 'León Center', x: 530, y: 460 },
  { name: 'Chinandega Center', x: 470, y: 440 },
  { name: 'Masaya Center', x: 635, y: 620 },
  { name: 'Granada Center', x: 675, y: 630 },
  { name: 'Carazo / Diriamba', x: 600, y: 650 },
  { name: 'Rivas Isthmus', x: 660, y: 735 },
  { name: 'San Carlos / Río San Juan', x: 840, y: 780 },
  { name: 'Bluefields / Costa Caribe Sur', x: 1020, y: 540 },
  { name: 'Nueva Guinea / Interior Sur', x: 920, y: 650 },
  { name: 'Siuna / Costa Caribe Norte', x: 990, y: 230 },
  { name: 'Puerto Cabezas / Bilwi', x: 1150, y: 120 }
]

const activeTravelers = ref<Traveler[]>([])
let timer: number | null = null

const getBezierPoint = (p0: number, p1: number, p2: number, t: number) => {
  return (1 - t) * (1 - t) * p0 + 2 * (1 - t) * t * p1 + t * t * p2
}

const getPartialPath = (startX: number, startY: number, cx: number, cy: number, destX: number, destY: number, t: number) => {
  if (t <= 0) return `M ${startX} ${startY}`
  if (t >= 1) return `M ${startX} ${startY} Q ${cx} ${cy} ${destX} ${destY}`

  const currentX = getBezierPoint(startX, cx, destX, t)
  const currentY = getBezierPoint(startY, cy, destY, t)
  const subCx = startX + (cx - startX) * t
  const subCy = startY + (cy - startY) * t

  return `M ${startX} ${startY} Q ${subCx} ${subCy} ${currentX} ${currentY}`
}

const generateRandomTraveler = () => {
  const origin = landPoints[Math.floor(Math.random() * landPoints.length)]
  let destination = landPoints[Math.floor(Math.random() * landPoints.length)]
  while (destination.name === origin.name) {
    destination = landPoints[Math.floor(Math.random() * landPoints.length)]
  }

  const startX = origin.x + (Math.random() - 0.5) * 20
  const startY = origin.y + (Math.random() - 0.5) * 20
  const destX = destination.x + (Math.random() - 0.5) * 20
  const destY = destination.y + (Math.random() - 0.5) * 20

  const dx = destX - startX
  const dy = destY - startY
  const distance = Math.sqrt(dx * dx + dy * dy)

  const minRadius = 2.2
  const calculatedRadius = minRadius + (distance / 450) * 2.8
  const radius = Math.min(Math.max(calculatedRadius, minRadius), 5.5)

  const midX = (startX + destX) / 2
  const midY = Math.min(startY, destY) - 50
  const randomJitterX = (Math.random() - 0.5) * 40
  const randomJitterY = (Math.random() - 0.5) * 40

  const traveler: Traveler = {
    id: Date.now() + Math.random(),
    startX,
    startY,
    destX,
    destY,
    cx: midX + randomJitterX,
    cy: midY + randomJitterY,
    progress: 0,
    radius
  }

  activeTravelers.value.push(traveler)

  const startTime = performance.now()
  const duration = Math.min(Math.max(distance * 2.2, 1400), 2800)

  const animate = (currentTime: number) => {
    const elapsed = currentTime - startTime
    const progress = Math.min(elapsed / duration, 1)

    const index = activeTravelers.value.findIndex(t => t.id === traveler.id)
    if (index !== -1) {
      activeTravelers.value[index].progress = progress
    }

    if (progress < 1) {
      requestAnimationFrame(animate)
    } else {
      activeTravelers.value = activeTravelers.value.filter(t => t.id !== traveler.id)
    }
  }

  requestAnimationFrame(animate)
}

onMounted(() => {
  timer = window.setInterval(generateRandomTraveler, 350)
})

onUnmounted(() => {
  if (timer) clearInterval(timer)
})
</script>

